<script setup lang="ts">
import {apiError} from './apiError';
import {ref,watch,computed} from 'vue';
const props=defineProps<{projectId:string;section?:string}>();const emit=defineEmits<{open:[id:string]}>();const records=ref<any[]>([]);const plans=ref<any[]>([]);const left=ref('');const right=ref('');const first=ref<any>(null);const second=ref<any>(null);const error=ref('');const working=ref(false);
async function api(path:string){const r=await fetch(path);const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));return d}
let archiveRequest=0;let comparisonRequest=0;
const condition=ref('all');
const loading=ref(false);const offset=ref(0);const total=ref(0);const kind=ref('all');const pageSize=20;
const selectedRecords=ref<any[]>([]);
const comparisonOptions=computed(()=>[...new Map([...selectedRecords.value,...records.value].map(r=>[r.id,r])).values()]);
watch(()=>props.projectId,()=>{offset.value=0;kind.value='all';++comparisonRequest;left.value='';right.value='';selectedRecords.value=[];first.value=null;second.value=null;working.value=false});
watch([()=>props.projectId,offset,kind,condition],async ([projectId])=>{
 const request=++archiveRequest;
 records.value=[];plans.value=[];error.value='';loading.value=true;
 try{const [newRecords,newPlans]=await Promise.all([api('/api/run-archive?project_id='+encodeURIComponent(projectId as string)+'&limit='+pageSize+'&offset='+offset.value+'&kind='+kind.value+'&operating_condition='+condition.value),api('/api/plans?project_id='+encodeURIComponent(projectId as string))]);if(request!==archiveRequest)return;records.value=newRecords.items;total.value=newRecords.total;plans.value=newPlans}
 catch(e){if(request===archiveRequest)error.value=String(e)}finally{if(request===archiveRequest)loading.value=false}
},{immediate:true});
watch([left,right],()=>{selectedRecords.value=comparisonOptions.value.filter(r=>r.id===left.value||r.id===right.value);++comparisonRequest;first.value=null;second.value=null;working.value=false;error.value=''});
async function compare(){const request=++comparisonRequest;working.value=true;error.value='';first.value=null;second.value=null;try{const [a,b]=await Promise.all([api('/api/runs/'+left.value),api('/api/runs/'+right.value)]);if(request!==comparisonRequest)return;first.value=a;second.value=b}catch(e){if(request===comparisonRequest)error.value=String(e)}finally{if(request===comparisonRequest)working.value=false}}
const comparable=computed(()=>first.value&&second.value&&first.value.input_csv===second.value.input_csv&&first.value.model===second.value.model&&JSON.stringify({wind_node:18,pv_node:30,voltage_min_pu:.95,voltage_max_pu:1.05,linear_voltage_guard_pu:.955,...first.value.network_parameters})===JSON.stringify({wind_node:18,pv_node:30,voltage_min_pu:.95,voltage_max_pu:1.05,linear_voltage_guard_pu:.955,...second.value.network_parameters})&&first.value.algorithm===second.value.algorithm&&first.value.branch_limit_kw===second.value.branch_limit_kw&&JSON.stringify(first.value.failed_lines)===JSON.stringify(second.value.failed_lines)&&JSON.stringify(first.value.stages)===JSON.stringify(second.value.stages)&&first.value.scenario_id===second.value.scenario_id&&first.value.production_sequence_id===second.value.production_sequence_id);
const metrics=[['max_power_deficit_kw','最大功率缺额 / kW'],['expected_energy_deficit_kwh','缺供电量 / kWh'],['critical_load_supply_ratio','关键负荷电量满足率 / 比例'],['loss_of_load_probability','缺供时段占比 / 比例']];
</script>
<template><p v-if="loading" role="status">正在读取本工程档案…</p><p class="error" v-if="error">{{error}}</p><article v-show="!section||section==='计算档案'" id="report-archive"><h3>工程计算档案</h3><label>结果类型<select v-model="kind" @change="offset=0"><option value="all">全部结果</option><option value="baseline">独立基准计算</option><option value="adjustment">策略与配置复核</option><option value="random">随机样本计算</option></select></label><label>运行工况<select v-model="condition" @change="offset=0"><option value="all">全部</option><option value="normal">常规运行</option><option value="extreme">极端保供</option><option value="unknown">工况未记录</option></select></label><p>共{{total}}条匹配结果，每页{{pageSize}}条；已选对比结果会在翻页或筛选后保留。</p><p v-if="!loading&&!records.length">当前筛选条件下暂无结果。</p><div class="scroll"><table><tr><th>计算时间</th><th>工程版本</th><th>模型</th><th>运行工况</th><th>来源</th><th>查看与导出</th></tr><tr v-for="r in records"><td>{{r.created}}</td><td>{{r.project_revision||'未关联'}}</td><td>{{r.model==='case33'?'IEEE33网络':'汇总模型'}}</td><td>{{r.operating_condition==='normal'?'常规运行':r.operating_condition==='extreme'?'极端保供':'工况未记录'}}</td><td>{{r.random_batch_id?'随机样本':r.baseline_run_id?'调整复核':'独立计算'}}<small v-if="r.baseline_run_id"> · 基准{{r.baseline_run_id.slice(0,8)}}</small></td><td><div class="row-actions"><button @click="emit('open',r.id)">查看</button><button @click="left=r.id">设为基准</button><button @click="right=r.id">设为对比</button></div> <a :href="'/api/runs/'+r.id+'/report'">报告</a> · <a :href="'/api/runs/'+r.id+'/csv'">CSV</a></td></tr></table></div><div class="actions"><button @click="offset=Math.max(0,offset-pageSize)" :disabled="loading||offset===0">上一页档案</button><span>第{{Math.floor(offset/pageSize)+1}} / {{Math.max(1,Math.ceil(total/pageSize))}}页</span><button @click="offset+=pageSize" :disabled="loading||offset+pageSize>=total">下一页档案</button></div></article><article v-show="!section||section==='方案对比'" id="report-comparison"><h3>计算结果对比</h3><p>可在不同页选取两次计算；切换工程时清空选择。</p><div class="actions"><select v-model="left" aria-label="基准计算"><option value="">选择基准计算</option><option v-for="r in comparisonOptions" :key="r.id" :value="r.id">{{r.created}} · {{r.id.slice(0,8)}}</option></select><select v-model="right" aria-label="对比计算"><option value="">选择对比计算</option><option v-for="r in comparisonOptions" :key="r.id" :value="r.id">{{r.created}} · {{r.id.slice(0,8)}}</option></select><button @click="compare" :disabled="!left||!right||working">加载对比</button></div><template v-if="first&&second"><p><a :href="'/api/comparison-report?baseline_id='+encodeURIComponent(first.id)+'&comparison_id='+encodeURIComponent(second.id)">导出计算对比报告 HTML</a></p><p class="notice">{{comparable?'输入时序、模型版本、支路约束、运行阶段、故障场景与生产序列引用一致，可结合资源参数差异评估效果。':'两次计算的时序、模型版本、接入节点、电压约束、支路约束、阶段、场景或生产序列引用不同，数值仅供并列查看，不能直接归因于配置改善。'}}</p><table><tr><th>指标</th><th>基准</th><th>对比</th><th>变化（对比−基准）</th></tr><tr v-for="[key,label] in metrics"><td>{{label}}</td><td>{{Number(first.metrics[key]).toFixed(4)}}</td><td>{{Number(second.metrics[key]).toFixed(4)}}</td><td>{{(second.metrics[key]-first.metrics[key]).toFixed(4)}}</td></tr></table></template></article><article v-show="!section||['方案对比','配置方案'].includes(section)" id="report-plans"><h3>配置建议档案</h3><p>研究代码简化枚举建议，需结合真实时序复核判断保供效果。</p><p v-if="!loading&&!plans.length">本工程尚无配置建议。</p><details v-for="p in plans"><summary>{{p.id.slice(0,8)}} · {{p.candidate_count}}个候选组合 · 投资估计{{p.evaluation.investment_cost}}元</summary><table><tr><th>储能功率 / kW</th><th>储能容量 / kWh</th><th>应急发电 / kW</th><th>移动资源 / 台</th></tr><tr><td>{{p.recommended_plan.storage_power_kw}}</td><td>{{p.recommended_plan.storage_energy_kwh}}</td><td>{{p.recommended_plan.emergency_gen_kw}}</td><td>{{p.recommended_plan.mobile_units}}</td></tr></table><button @click="emit('open',p.source_run_id)">查看基准计算</button></details></article></template>
<style scoped>.actions{flex-wrap:wrap;align-items:center}.row-actions{display:flex;gap:5px;flex-wrap:wrap;margin-bottom:6px}.row-actions button{font-size:12px;padding:5px 7px}select{max-width:100%;padding:9px;border:1px solid #c8dcdf}details{padding:16px;border-bottom:1px solid #e0ebec}summary{cursor:pointer}.scroll{max-height:400px}</style>
